# ─── Module: board_qa ───────────────────────────────────────────────────────
# RCDome Q&A AI — the submodule of the Digital Molecular RCD Board.
#
# Hybrid model, analogous to CancerPredictor's "Clinical Q&A AI":
#   (1) RCDome database + decoder payload (the queried entity) as the source;
#   (2) a governed DeepSeek reasoning layer (common knowledge allowed, but
#       every factual claim must be traceable to the injected data);
#   (3) domain boundary + refusal templates;
#   (4) exact disclaimer appended.
#
# The three "Suggested Queries" generated by the board synthesis appear as
# clickable chips; the user may also ask free-form questions.
# Follows the same chat governance as benchmark Test 9 (sourced, hedged,
# no invented PMID).

BOARD_QA_DISCLAIMER <- paste0(
  "The interpretations presented above should be considered hypothesis-generating ",
  "and are intended to support biological exploration of regulated cell death. ",
  "The proposed mechanisms and gene\u2013RCD associations are inferred from the ",
  "RCDome database and the RCDome decoder. The strength of evidence varies across ",
  "associations: some are well-founded and unambiguous, while others are provisional. ",
  "Users should independently cross-validate each association and, in some instances, ",
  "pursue additional experimental validation."
)

BOARD_QA_REFUSAL <- paste0(
  "This question falls outside the scope of the RCDome Digital Molecular Board, ",
  "which answers regulated-cell-death and gene-association questions based only ",
  "on the RCDome database and the RCDome decoder."
)

# RAG retrieval: full four-dimension records for the entities/genes the question
# mentions (keyword-based; no extra model call). The complete gene index (all
# associations, names only) is injected separately, so nothing is ever deleted.
build_rag_records <- function(question, default_entity = NULL, max_chars = 60000) {
  if (is.null(question) || !nzchar(question)) return("")
  if (!exists("genes_df", inherits = TRUE) || nrow(genes_df) == 0) return("")

  q <- tolower(question)

  # 1) Entity match: canonical name or its stem (so "apoptotic" matches Apoptosis)
  ents <- sort(unique(genes_df$rcd_form_canonical))
  matched_ents <- ents[sapply(ents, function(e) {
    le <- tolower(e)
    stem <- sub("sis$", "", le)
    grepl(le, q, fixed = TRUE) || (nchar(stem) >= 5 && grepl(stem, q, fixed = TRUE))
  })]

  # 2) Gene match: tokens equal to a gene symbol (case-insensitive); hyphenated
  #    compounds such as "XIAP-Apoptosis" are split so the gene is still matched.
  raw <- unique(unlist(strsplit(question, "[^A-Za-z0-9-]+")))
  toks <- unique(unlist(lapply(raw, function(t) strsplit(t, "-", fixed = TRUE)[[1]])))
  genes_all <- unique(genes_df$gene_symbol)
  # Match 1-2 character gene symbols FIRST (TF, AR, C3, KL, ...) so the length
  # filter below does not drop them. Longer tokens keep the original order
  # (length -> stopwords -> gene match) to preserve the stopword guard (e.g.,
  # "was" vs the WAS gene).
  short_genes <- toks[nchar(toks) < 3 & toupper(toks) %in% toupper(genes_all)]
  toks <- toks[nchar(toks) >= 3]
  stopwords <- c("THE", "AND", "FOR", "ARE", "WAS", "WERE", "WITH", "WHAT",
                 "WHICH", "GENE", "GENES", "FORM", "FORMS", "THAT", "THIS",
                 "THESE", "THOSE", "HOW", "WHY", "WHO", "WHOM", "YOU", "YOUR",
                 "FROM", "HAVE", "HAS", "ITS", "NOT", "RCD", "RCDOME")
  toks <- toks[!toupper(toks) %in% stopwords]
  matched_genes <- c(short_genes, toks[toupper(toks) %in% toupper(genes_all)])

  # 3) Fall back to the current entity when nothing matched
  if (length(matched_ents) == 0 && length(matched_genes) == 0) {
    matched_ents <- default_entity
  }

  # 4) Retrieve the full records
  keep <- rep(FALSE, nrow(genes_df))
  if (length(matched_ents) > 0) keep <- keep | (genes_df$rcd_form_canonical %in% matched_ents)
  if (length(matched_genes) > 0) keep <- keep | (genes_df$gene_symbol %in% matched_genes)
  if (!any(keep)) return("")
  rows <- genes_df[keep, ]
  rows <- rows[!duplicated(paste(rows$gene_symbol, rows$rcd_form_canonical)), ]

  # 5) Prioritize: explicitly-mentioned genes first, then MECHANISTIC > ET1/ET2 >
  #    EXECUTOR > REGULATOR, so a queried gene is never pushed out by the budget.
  is_explicit_gene <- rows$gene_symbol %in% matched_genes
  ord <- order(
    is_explicit_gene,
    (rows$mechanistic_class == "MECHANISTIC"),
    (rows$evidence_tier %in% c("ET1", "ET2")),
    (rows$cot_role == "EXECUTOR"),
    (rows$cot_role == "REGULATOR"),
    decreasing = TRUE
  )
  rows <- rows[ord, ]

  # 6) Format with the full four dimensions + PMID
  mc <- ifelse(is.na(rows$mechanistic_class), "NA", as.character(rows$mechanistic_class))
  rl <- ifelse(is.na(rows$cot_role), "NA", as.character(rows$cot_role))
  dr <- ifelse(is.na(rows$cot_direction), "NA", as.character(rows$cot_direction))
  ti <- ifelse(is.na(rows$evidence_tier), "NA", as.character(rows$evidence_tier))
  ct <- ifelse(is.na(rows$confidence_tier), "NA", as.character(rows$confidence_tier))
  eb <- ifelse(is.na(rows$evidence_basis), "NA", as.character(rows$evidence_basis))
  cs <- ifelse(is.na(rows$confidence_score), "NA", as.character(rows$confidence_score))
  ef <- ifelse(is.na(rows$final_role), "NA", paste0(as.character(rows$final_role), "/", as.character(rows$final_direction), "/", as.character(rows$final_mechanistic)))
  cm <- ifelse(is.na(rows$rcd_gene_type) | is.na(rows$role_direction), "NA", paste0(as.character(rows$rcd_gene_type), "/", as.character(rows$role_direction)))
  cn <- ifelse(is.na(rows$consensus_role) | is.na(rows$consensus_direction), "NA", paste0(as.character(rows$consensus_role), "/", as.character(rows$consensus_direction)))
  gp <- ifelse(is.na(rows$gpt_mapped_role) | is.na(rows$gpt_mapped_dir), "NA", paste0(as.character(rows$gpt_mapped_role), "/", as.character(rows$gpt_mapped_dir)))
  c1 <- ifelse(is.na(rows$curator_1_mapped_role) | is.na(rows$curator_1_mapped_dir), "NA", paste0(as.character(rows$curator_1_mapped_role), "/", as.character(rows$curator_1_mapped_dir)))
  c2 <- ifelse(is.na(rows$curator_2_mapped_role) | is.na(rows$curator_2_mapped_dir), "NA", paste0(as.character(rows$curator_2_mapped_role), "/", as.character(rows$curator_2_mapped_dir)))
  fv <- ifelse(is.na(rows$final_verdict), "NA", as.character(rows$final_verdict))
  ds <- ifelse(is.na(rows$decision_status), "NA", as.character(rows$decision_status))
  pm <- vapply(rows$pmid_list, function(p) {
    ps <- strsplit(as.character(p), ";", fixed=TRUE)[[1]]
    ps <- ps[!is.na(ps) & ps != ""]
    if (length(ps) == 0) return("NA")
    if (length(ps) <= 2) return(paste(ps, collapse=";"))
    paste0(paste(ps[1:2], collapse=";"), "; +", length(ps)-2, " more")
  }, character(1))
  lines <- paste0("- ", rows$gene_symbol, " (", rows$rcd_form_canonical, ": ",
                  "mc=", mc, " | DS=", rl, "/", dr,
                  " | Compiled=", cm, " | Consensus=", cn, " | GPT=", gp,
                  " | Cur1=", c1, " | Cur2=", c2, " | EF=", ef, " | verdict=", fv,
                  " | ET=", ti, " | CT=", ct, " | PMID=", pm, ")")

  # 7) Budget cap (most informative records first, within the budget)
  txt <- ""
  for (ln in lines) {
    if (nchar(txt) + nchar(ln) + 1 > max_chars) break
    txt <- paste0(txt, ln, "\n")
  }
  txt
}

# Build the hybrid system prompt for the Q&A chat.
build_board_qa_prompt <- function(b, question = NULL) {
  entity        <- b$entity %||% "unknown entity"
  decoder_fields<- b$decoder_fields %||% "not recorded"

  # Full decoder + gene index (all 53 entities) so the Q&A can answer about ANY
  # entity, not only the one currently loaded on the board.
  full_decoder <- if (exists("decoder_df", inherits = TRUE) && nrow(decoder_df) > 0) {
    paste(apply(decoder_df, 1, function(r) {
      paste0("- ", r[["rcd_form"]], ": ", r[["operational_definition"]],
             " (category: ", r[["category"]], "; gate: ", r[["hard_gate_status"]],
             "; key molecules: ", r[["key_molecules"]],
             "; founding PMID: ", r[["founding_pmid"]], ")")
    }), collapse = "\n")
  } else ""

  full_genes <- if (exists("genes_df", inherits = TRUE) && nrow(genes_df) > 0) {
    ents <- sort(unique(genes_df$rcd_form_canonical))
    paste(sapply(ents, function(e) {
      g <- sort(unique(genes_df$gene_symbol[genes_df$rcd_form_canonical == e]))
      paste0("- ", e, ": ", paste(g, collapse = ", "))
    }), collapse = "\n")
  } else ""

  # RAG: full four-dimension records for the entities/genes the question mentions.
  rag <- build_rag_records(question, default_entity = entity)

  paste0(
    "You are the RCDome Q&A assistant, part of the RCDome Digital Molecular RCD Board. ",
    "You combine (1) the RCDome database and RCDome decoder (the authoritative facts) ",
    "with (2) your general biological knowledge for fluent, expert articulation and ",
    "reasoning. You may answer about ANY of the 53 entities and may cross-reference ",
    "genes and mechanisms ACROSS entities (for example, genes shared between apoptosis ",
    "and necroptosis, or an entity and its parent or subtype). Do not restrict yourself ",
    "to the currently selected entity.\n\n",
    "FACTUAL DISCIPLINE (zero hallucination): every specific factual claim (a gene ",
    "symbol, a PMID, a role, a direction, an operational definition, an evidence tier) ",
    "must be traceable to the provided RCDome data. Never invent a gene, PMID, or fact. ",
    "Cite only PMIDs present in the data. If a specific fact is not in the data, say so ",
    "honestly rather than fabricate it.\n\n",
    "NOTE: Evidence Tier (ET) and Confidence Tier (CT) are DIFFERENT metrics: ET ",
    "combines source count and LLM validation; CT derives from the weighted ",
    "source-channel confidence score. Both coexist per record; never conflate them.\n\n",
    "REFERENCE DISCIPLINE: a gene\u2013RCD association citation must use the ",
    "gene-specific association PMID, never the entity founding PMID; an entity ",
    "definition citation must use the entity founding PMID. Never interchange them. If a record lists multiple PMIDs, cite the first one.\n\n",
    "CLASSIFICATION LAYERS (the labels used in the Gene Catalog):\n",
    "- \"Evidence-first\" (final resolution) = final_role / final_direction / final_mechanistic\n",
    "- \"DeepSeek\" = cot_role / cot_direction / cot_mechanistic\n",
    "- \"Compiled gene role\" = rcd_gene_type / role_direction\n",
    "- \"Consensus\" = consensus_role / consensus_direction / consensus_mechanistic\n",
    "- \"GPT\" = gpt_mapped_role / gpt_mapped_dir\n",
    "- \"Curator 1\" = curator_1_mapped_role / curator_1_mapped_dir\n",
    "- \"Curator 2\" = curator_2_mapped_role / curator_2_mapped_dir\n",
    "For general questions and the synthesis, lead with the Evidence-first (final) layer; mention the other layers only when the user asks for them specifically.\n",
    "When the user asks for a SPECIFIC layer, report THAT layer's values, clearly labeled. When layers diverge, list them in separate rows with labels; never conflate them or present one layer as another.\n\n",
    "STYLE: hedge all interpretations (\u201cmay suggest\u201d, \u201cis consistent ",
    "with\u201d, \u201crequires validation\u201d). Name the source in every factual claim ",
    "(\u201cthe RCDome database records\u2026\u201d, \u201cthe RCDome decoder ",
    "defines\u2026\u201d). Write prose only: no bullet lists, no bold, no headers.\n\n",
    "DOMAIN BOUNDARY:\n",
    "- Questions about regulated cell death, gene associations, roles, directions, ",
    "evidence maturity, key molecules, or ontological relationships: answer from the data.\n",
    "- Questions about clinical treatment or anything outside regulated-cell-death ",
    "biology: refuse with the exact refusal sentence below.\n\n",
    "REFUSAL (exact): \u201c", BOARD_QA_REFUSAL, "\u201d\n\n",
    "LANGUAGE: answer ONLY in English. If the question is in any language other than English, ",
    "reply ONLY with: \u201cThis assistant answers only in English. Please reformulate ",
    "your question in English.\u201d\n\n",
    "End every non-refusal answer with the exact disclaimer:\n",
    "\u201c", BOARD_QA_DISCLAIMER, "\u201d\n\n",
    "RCDome decoder (ALL 53 entities, operational definitions):\n", full_decoder, "\n\n",
    "RCDome database (ALL genes per entity):\n", full_genes, "\n\n",
    if (nzchar(rag)) paste0(
      "RCDome database (FULL records for the entities/genes mentioned in the question; ",
      "format: gene(form: mechanistic_class | role | direction | ET:evidence_tier | CT:confidence_tier | PMID)):\n",
      rag, "\n\n"
    ) else "",
    "Current entity on the board: ", entity, "\n",
    "Current gene on the board: ", if (is.null(b$gene) || b$gene == "") "(none selected)" else b$gene, "\n",
    "RCDome decoder (current entity ontology):\n", decoder_fields
  )
}

mod_board_qa_ui <- function(id) {
  ns <- NS(id)

  tagList(
    div(
      class = "rcdchat-shell",

      # ── Top bar ──────────────────────────────────────────────────────
      div(
        class = "rcdchat-topbar",
        div(
          class = "rcdchat-title-group",
          div(class = "rcdchat-mark", "RQ"),
          div(
            div(class = "rcdchat-title", HTML(paste0(rcdome_span(), " Q&A AI"))),
            uiOutput(ns("context_badge"))
          )
        ),
        actionButton(ns("qa_clear"), HTML("+&nbsp;New chat"),
                     class = "rcdchat-newchat-btn")
      ),

      # ── Suggested queries (from the board synthesis) ──────────────────
      div(class = "rcdchat-suggested", uiOutput(ns("suggested_chips"))),

      # ── Messages ─────────────────────────────────────────────────────
      div(
        id = ns("qa_scroll"),
        class = "rcdchat-scroll",
        uiOutput(ns("qa_ui"))
      ),

      # ── Composer ─────────────────────────────────────────────────────
      div(
        class = "rcdchat-composer",
        div(
          class = "rcdchat-input-shell",
          tags$textarea(
            id = ns("qa_input"),
            class = "form-control rcdchat-textarea",
            rows = "1",
            placeholder = "Ask about this RCD entity..."
          ),
          actionButton(ns("qa_send"), HTML("&#8593;"),
                       class = "rcdchat-send-btn")
        ),
        div(class = "rcdchat-hint",
            "RCDome Q&A answers from the RCDome database and decoder. Enter to send.")
      )
    ),

    # ── Enter-to-send + auto-scroll ─────────────────────────────────────
    tags$script(HTML(sprintf("
      (function() {
        var inputId  = '%s';
        var sendId   = '%s';
        var scrollId = '%s';
        $(document).on('keydown', '#' + inputId, function(e) {
          if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            $('#' + sendId).trigger('click');
          }
        });
        $(document).on('shiny:value', function(ev) {
          if (ev.name === '%s') {
            var el = document.getElementById(scrollId);
            if (el) el.scrollTop = el.scrollHeight;
            var ta = document.getElementById(inputId);
            if (ta) { ta.value = ''; ta.style.height = 'auto'; }
          }
        });
      })();

      function copyQAText(id) {
        var el = document.getElementById(id);
        if (!el) return;
        var q = el.getAttribute('data-query') || '';
        var a = el.innerText || el.textContent || '';
        var txt = q ? ('Question: ' + q + '\\n\\nAnswer: ' + a) : a;
        if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText(txt);
        } else {
          var ta = document.createElement('textarea');
          ta.value = txt; ta.style.position = 'fixed'; ta.style.opacity = '0';
          document.body.appendChild(ta); ta.select();
          try { document.execCommand('copy'); } catch(e) {}
          document.body.removeChild(ta);
        }
      }
    ", ns("qa_input"), ns("qa_send"), ns("qa_scroll"), ns("qa_ui"))))
  )
}

mod_board_qa_server <- function(id, board_reactive, pending_query = NULL) {
  moduleServer(id, function(input, output, session) {
    ns <- session$ns

    messages <- reactiveVal(list())

    # Welcome message when an entity is loaded from the board
    observeEvent(board_reactive(), {
      b <- board_reactive()
      if (is.null(b) || length(b) == 0) return()
      ent <- b$entity %||% "this entity"
      messages(list(list(
        role = "assistant",
        content = sprintf(
          "RCDome Q&A \u2014 %s. Ask about associated genes, required genes, evidence maturity, key molecules, or ontological relationships.",
          ent
        )
      )))
    }, ignoreNULL = TRUE)

    output$context_badge <- renderUI({
      b <- board_reactive()
      if (is.null(b) || length(b) == 0) {
        tags$div(class = "rcdchat-badge", "No entity loaded")
      } else {
        tags$div(class = "rcdchat-badge rcdchat-badge-gene",
                 paste0("Entity: ", b$entity %||% "?"))
      }
    })

    # Suggested-query chips
    output$suggested_chips <- renderUI({
      b <- board_reactive()
      qs <- b$suggested_queries %||% character(0)
      if (length(qs) == 0) return(NULL)
      lapply(seq_along(qs), function(i) {
        actionButton(ns(paste0("sq_", i)), qs[i], class = "rcdchat-chip")
      })
    })

    # Clicking a chip sends the question
    lapply(1:3, function(i) {
      observeEvent(input[[paste0("sq_", i)]], {
        b <- board_reactive()
        qs <- b$suggested_queries %||% character(0)
        if (i <= length(qs)) send_query(qs[i])
      }, ignoreNULL = TRUE)
    })

    # Core send logic
    send_query <- function(txt) {
      txt <- trimws(txt)
      if (is.null(txt) || txt == "") return()

      b <- board_reactive()
      if (is.null(b) || length(b) == 0) return()

      api_key <- Sys.getenv("DEEPSEEK_API_KEY", unset = "")
      if (api_key == "") {
        msgs <- messages()
        msgs[[length(msgs) + 1]] <- list(
          role = "assistant",
          content = "Error: DEEPSEEK_API_KEY is not set."
        )
        messages(msgs)
        return()
      }

      msgs <- messages()
      msgs[[length(msgs) + 1]] <- list(role = "user", content = txt)
      messages(msgs)

      prompt <- list(
        list(role = "system", content = build_board_qa_prompt(b, txt)),
        list(role = "user", content = txt)
      )

      # typing indicator
      msgs <- messages()
      msgs[[length(msgs) + 1]] <- list(role = "assistant", content = "__typing__")
      messages(msgs)

      reply <- tryCatch({
        resp <- httr::POST(
          "https://api.deepseek.com/v1/chat/completions",
          httr::add_headers(
            Authorization = paste("Bearer", api_key),
            "Content-Type" = "application/json"
          ),
          body = jsonlite::toJSON(list(
            model = "deepseek-chat", messages = prompt, temperature = 0.3,
            max_tokens = 1500
          ), auto_unbox = TRUE),
          encode = "raw",
          httr::timeout(180)
        )
        status <- httr::status_code(resp)
        body   <- httr::content(resp, "text", encoding = "UTF-8")
        if (status != 200) {
          paste0("Error: DeepSeek HTTP ", status)
        } else {
          jsonlite::fromJSON(body)$choices$message$content[1]
        }
      }, error = function(e) paste0("Error: ", conditionMessage(e)))

      reply <- htmltools::htmlEscape(reply)
      # markdown bold -> HTML strong; PMIDs -> clickable
      reply <- gsub("\\*\\*(.+?)\\*\\*", "<strong>\\1</strong>", reply, perl = TRUE)
      reply <- gsub("PMID[ :](\\d+)",
                    "<a href='https://pubmed.ncbi.nlm.nih.gov/\\1' target='_blank'>PMID \\1</a>",
                    reply, perl = TRUE)

      msgs <- messages()
      msgs[[length(msgs)]] <- list(role = "assistant", content = reply)
      messages(msgs)
    }

    observeEvent(input$qa_send, { send_query(input$qa_input) })

    # auto-send a pending query (from an example-query click)
    if (!is.null(pending_query)) {
      observeEvent(pending_query(), {
        q <- pending_query()
        if (!is.null(q) && nzchar(q)) send_query(q)
      }, ignoreNULL = TRUE)
    }

    observeEvent(input$qa_clear, {
      b <- board_reactive()
      ent <- b$entity %||% "this entity"
      messages(list(list(
        role = "assistant",
        content = sprintf(
          "RCDome Q&A \u2014 %s. Ask about associated genes, required genes, evidence maturity, key molecules, or ontological relationships.",
          ent
        )
      )))
    })

    # Render chat
    output$qa_ui <- renderUI({
      msgs <- messages()
      if (length(msgs) == 0) {
        return(tags$div(
          class = "rcdchat-empty",
          "Run a Digital Molecular RCD Board synthesis to load an entity, then ask follow-up questions here."
        ))
      }

      lapply(seq_along(msgs), function(i) {
        m <- msgs[[i]]
        is_user   <- m$role == "user"
        is_typing <- identical(m$content, "__typing__")
        mid <- paste0("qamsg-", i)
        q <- ""
        if (!is_user && i > 1 && msgs[[i-1]]$role == "user") q <- msgs[[i-1]]$content

        if (is_user) {
          tags$div(
            class = "rcdchat-row rcdchat-row-user",
            tags$div(class = "rcdchat-bubble-user", HTML(gsub("\n", "<br>", htmltools::htmlEscape(m$content))))
          )
        } else {
          tags$div(
            class = "rcdchat-row rcdchat-row-assistant",
            tags$div(class = "rcdchat-avatar", "RQ"),
            if (is_typing) {
              tags$div(
                class = "rcdchat-typing",
                tags$span(class = "dot"), tags$span(class = "dot"), tags$span(class = "dot")
              )
            } else {
              tags$div(
                style = "flex:1; min-width:0;",
                tags$div(id = mid, class = "rcdchat-assistant-text",
                         `data-query` = htmltools::htmlEscape(q),
                         HTML(gsub("\n", "<br>", m$content))),
                tags$button(
                  class = "btn rcdchat-copy-btn",
                  onclick = sprintf("copyQAText('%s')", mid),
                  title = "Copy question and answer to clipboard",
                  "Copy"
                )
              )
            }
          )
        }
      })
    })

    messages

  })
}
